import{_ as r,C as s,o as d,c as n,ag as o,E as a}from"./chunks/framework.CtWPcAmt.js";const m=JSON.parse('{"title":"Product Barcode","description":"","frontmatter":{},"headers":[],"relativePath":"catalog/product-barcode.md","filePath":"catalog/product-barcode.md","lastUpdated":1786111645000}'),c={name:"catalog/product-barcode.md"};function l(i,e,u,p,g,h){const t=s("ImagePopup");return d(),n("div",null,[e[0]||(e[0]=o('<h1 id="product-barcode" tabindex="-1">Product Barcode <a class="header-anchor" href="#product-barcode" aria-label="Permalink to &quot;Product Barcode&quot;">​</a></h1><p>Every seller product can carry a scannable <strong>barcode</strong>. The barcode image is generated automatically from a value you set — you never upload it — and can be generated and printed in bulk for stock, picking, and fulfilment.</p><div class="info custom-block"><p class="custom-block-title">What you&#39;ll learn</p><ul><li>How a product&#39;s barcode is set and generated</li><li>Which barcode symbologies are supported</li><li>How to generate, print, and download barcodes</li></ul></div><h2 id="setting-a-barcode-on-a-product" tabindex="-1">Setting a barcode on a product <a class="header-anchor" href="#setting-a-barcode-on-a-product" aria-label="Permalink to &quot;Setting a barcode on a product&quot;">​</a></h2><p>Open a product from <strong>Catalog → Products</strong> and go to the <strong>Barcode</strong> tab on the edit form.</p>',5)),a(t,{src:"/images/product-barcode/barcode-tab.png",alt:"Barcode tab on the product edit form"}),e[1]||(e[1]=o('<ul><li><strong>Barcode Value</strong> — the value encoded in the barcode. Set it to whatever the barcode should represent (a product code, GTIN, and so on). If you leave it empty, <strong>no barcode is generated when you save</strong> — but the bulk <strong>Generate Barcode</strong> action can still produce one, deriving the value from the product&#39;s ID.</li><li><strong>Barcode</strong> — the generated image. It is <strong>read-only and created automatically every time you save the product</strong>, and refreshes whenever the value changes. Once generated, a <strong>Download Barcode</strong> link gives you a single-product PDF.</li></ul><p>Save the product and the barcode image is generated from the value.</p><div class="info custom-block"><p class="custom-block-title">Supported symbologies</p><p>Barcodes are generated as <strong>Code 128</strong>, <strong>EAN-13</strong>, or <strong>UPC-A</strong>. A default symbology applies automatically; EAN-13 / UPC-A values are adjusted to a valid GTIN where needed. QR codes are not used here.</p></div><h2 id="barcodes-on-the-products-list" tabindex="-1">Barcodes on the products list <a class="header-anchor" href="#barcodes-on-the-products-list" aria-label="Permalink to &quot;Barcodes on the products list&quot;">​</a></h2><p>The products list shows a <strong>Barcode</strong> column with each product&#39;s state (for example, blank until a barcode has been generated), and a <strong>Barcode Value</strong> column you can search and filter.</p>',5)),a(t,{src:"/images/product-barcode/products-list.png",alt:"Barcode column on the seller products list"}),e[2]||(e[2]=o('<p>Select one or more products with the checkboxes and use the bulk actions:</p><ul><li><strong>Generate Barcode</strong> — generate barcodes for the selected products; you choose the symbology (<strong>Code 128 / EAN-13 / UPC-A</strong>). Products without a value get one derived automatically. The result reports how many were generated and how many were skipped.</li><li><strong>Print Barcodes</strong> — download a single PDF of the selected products&#39; barcodes — a table of <strong>ID</strong>, <strong>Name</strong>, and the <strong>barcode image + value</strong> — ready to print onto labels.</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Set <strong>Barcode Value</strong> to the GTIN or product code you already use in your inventory system, so the printed barcode scans to the same identifier everywhere.</p></div>',3))])}const _=r(c,[["render",l]]);export{m as __pageData,_ as default};
